function persistProjectDocuments(projectId,documents){
 const write=async()=>{reloadGeneration++;const next=structuredClone(state),project=[next,...(next.projects||[])].find(p=>p.project.id===projectId);if(!project)throw Error('문서를 저장할 프로젝트를 찾을 수 없습니다.');project.documents=typeof documents==='function'?documents(project.documents||[]):structuredClone(documents);const fresh=await saveWorkspace(next);state=adoptProjectWorkspace(fresh,state.project.id);rememberProjectNames();return [state,...(state.projects||[])].find(p=>p.project.id===projectId);};
 const result=pending.then(write);pending=result.catch(()=>{});return result;
}
function removeLegacyProjectReferences(projectId,expected){
 const write=async()=>{reloadGeneration++;const next=structuredClone(state),project=[next,...(next.projects||[])].find(p=>p.project.id===projectId);if(!project)throw Error('프로젝트를 찾을 수 없습니다.');for(const ref of expected){const current=project.refs.find(item=>item.id===ref.id);if(!current||current.libraryId||JSON.stringify(current)!==JSON.stringify(ref))throw Error('자료가 변경되었습니다. 새로고침 후 다시 선택해 주세요.');}const ids=new Set(expected.map(ref=>ref.id));project.refs=project.refs.filter(ref=>!ids.has(ref.id));for(const camera of [...project.cameras,...project.contents.flatMap(shoot=>shoot.configuration?.cameras||[])])camera.refs=camera.refs.filter(id=>!ids.has(id));const fresh=await saveWorkspace(next);state=adoptProjectWorkspace(fresh,state.project.id);return state;};const result=pending.then(write);pending=result.catch(()=>{});return result;
}
async function reloadAfterMutation(){
  const request=++reloadGeneration;
  await pending;
  if(!calendarEditorCanLeave()||!schoolCanLeave()||documentsDraftPending()||failed||saving||request!==reloadGeneration||editingDialog()||unsavedProjectSettings()||inventoryDraftPending()||adminProjectsDraftPending()||siteRoleManagementDraftPending()||accountDeletionDraftPending()||selfDeletionDraftPending())return;
  const generation=saveGeneration;
  const accept=()=>calendarEditorCanLeave()&&schoolCanLeave()&&!documentsDraftPending()&&!failed&&!saving&&generation===saveGeneration&&request===reloadGeneration&&!editingDialog()&&!unsavedProjectSettings()&&!inventoryDraftPending()&&!adminProjectsDraftPending()&&!siteRoleManagementDraftPending()&&!accountDeletionDraftPending()&&!selfDeletionDraftPending();
  const fresh=await loadWorkspace({accept});
  if(!fresh||!accept())return;
  state=adoptProjectWorkspace(fresh,state.project.id);rememberProjectNames();render();
}

// Uploads can finish after navigation or a specialized save. Attach only after
// its response is adopted; a failed save retains the queue for explicit retry.
const pendingAttachments=[];
let uploadsInFlight=0;
function flushUploadedAttachments(){
  if(saving||failed||!pendingAttachments.length)return;
  const attach=pendingAttachments[0];
  try{attach();pendingAttachments.shift();save();}catch(error){alert(error.message);}
}
async function uploadAttachment(file,attach){
  uploadsInFlight++;
  try{const result=await upload(file);pendingAttachments.push(()=>attach(result));flushUploadedAttachments();}
  finally{uploadsInFlight--;}
}

function save({focusGearId,focusFlagId,focusLayoutId,focusTaskId,focusTaskEditId,focusProjectId=state.project.id,operation}={}){
  if(failed)return;
  lastSaveOptions={focusGearId,focusFlagId,focusLayoutId,focusTaskId,focusTaskEditId,focusProjectId,operation};saveError='';saveConflict=false;
  recordHistory(true);
  saving=true;render();
  const snapshot=structuredClone(state),generation=++saveGeneration;
  pending=pending.then(()=>operation?operation():saveWorkspace(snapshot)).then(saved=>{if(generation!==saveGeneration)return;if(saved){state=adoptProjectWorkspace(saved,state.project.id);rememberProjectNames();}saving=false;lastSaveOptions=null;render();if(state.project.id===focusProjectId){if(focusGearId)[...document.querySelectorAll('[data-toggle-gear]')].find(b=>b.dataset.toggleGear===focusGearId)?.focus();if(focusFlagId)document.querySelector(`[data-flag-task="${focusFlagId}"]`)?.focus();if(focusLayoutId)document.querySelector(`[data-layout-id="${focusLayoutId}"]`)?.focus();if(focusTaskId)document.querySelector(`[data-task="${focusTaskId}"]`)?.focus();if(focusTaskEditId)document.querySelector(`[data-edit-task="${focusTaskEditId}"]`)?.focus();}flushUploadedAttachments();}).catch(error=>{if(generation!==saveGeneration)return;failed=true;saving=false;saveError=error.message;saveConflict=error.status===409;render();document.querySelector('[data-action=retry-save]')?.focus();});
}
