function shootDetailPage(shootPage){
 const c=state.contents.find(item=>item.id===shootPage.id);if(!c)return '<p>촬영을 찾을 수 없습니다.</p>';
 const tab=shootPage.tab||'info';
 return `<article class="shoot-detail-page" data-shoot-page="${esc(c.id)}"><div class="shoot-detail-heading"><button class="btn" data-action="shoot-back">뒤로가기</button><h2>${esc(c.name)}</h2>${status(c.status)}</div><div class="shoot-detail-tabs" role="tablist" aria-label="촬영 상세">${[['info','정보'],['configuration','촬영 구성'],['materials','자료'],['tasks','할 일']].map(([key,label])=>`<button type="button" role="tab" id="shoot-tab-${key}" aria-controls="shoot-panel-${key}" aria-selected="${tab===key}" tabindex="${tab===key?'0':'-1'}" data-shoot-tab="${key}">${label}</button>`).join('')}</div><section id="shoot-panel-info" role="tabpanel" aria-labelledby="shoot-tab-info" ${tab==='info'?'':'hidden'}><div class="card"><h3>촬영 정보</h3><form class="form" data-form="content-edit" data-id="${esc(c.id)}">${[['date','촬영일'],['name','촬영 이름'],['time','시간'],['location','장소']].map(([key,label])=>`<label class="field">${label}<input name="${key}" ${key==='date'?'type="date"':''} value="${esc(key==='date'?(c.date||state.project.date):c[key])}" ${key==='date'?'':'required'} maxlength="2000"></label>`).join('')}<button class="btn primary">촬영 정보 저장</button></form></div></section><section id="shoot-panel-materials" role="tabpanel" aria-labelledby="shoot-tab-materials" ${tab==='materials'?'':'hidden'}><div class="grid two"><div class="card"><h3>PDF 대본</h3><p>${c.script?'대본 연결됨':'대본 미등록'}</p><input aria-label="PDF 대본 업로드" type="file" accept="application/pdf" data-script-file="${esc(c.id)}">${c.scriptFile?`<iframe title="대본 미리보기" src="/api/files/${esc(c.scriptFile)}"></iframe><a class="btn" href="/api/files/${esc(c.scriptFile)}?download">원본 다운로드</a>`:'<p>PDF 대본을 등록하세요.</p>'}</div><div class="card"><h3>연결 자료</h3>${btn('문서','modal-refs')}</div></div></section>${shootManagement(state,c,{tab})}</article>`;
}
function captureShootForms(){
 const shoot=activeShootPage(),root=document.querySelector('[data-shoot-page]');if(!shoot||root?.dataset.shootPage!==shoot.id)return;
 shoot.rentalModel=root.querySelector('[data-shoot-rental]')?.catalogModel||null;
 shoot.openDetails=[...root.querySelectorAll('details')].map(n=>n.open);
 shoot.formDrafts=Object.fromEntries([...root.querySelectorAll('form')].map(form=>[form.dataset.form||[...form.attributes].find(a=>a.name.startsWith('data-shoot-'))?.name,[...form.elements].filter(n=>n.name&&n.type!=='file').map(n=>({name:n.name,type:n.type,value:n.value,checked:n.checked}))]));
}
function restoreShootForms(){
 const shoot=activeShootPage();if(!shoot?.formDrafts)return;
 document.querySelectorAll('[data-shoot-page] details').forEach((n,index)=>{n.open=Boolean(shoot.openDetails?.[index]);});
 for(const form of document.querySelectorAll('[data-shoot-page] form')){const key=form.dataset.form||[...form.attributes].find(a=>a.name.startsWith('data-shoot-'))?.name;for(const draft of shoot.formDrafts[key]||[]){const n=draftControl(form,draft);if(n){if(['radio','checkbox'].includes(n.type))n.checked=draft.checked;else n.value=draft.value;}}}
}
function bindShootPage(){

 const tabs=[...document.querySelectorAll('[data-shoot-tab]')];
 for(const button of tabs){button.onclick=()=>{captureModalDraft();captureShootForms();activeShootPage().tab=button.dataset.shootTab;recordHistory();render();document.querySelector('[data-shoot-tab="'+button.dataset.shootTab+'"]').focus();};button.onkeydown=event=>{let index=tabs.indexOf(button);if(event.key==='ArrowRight')index=(index+1)%tabs.length;else if(event.key==='ArrowLeft')index=(index+tabs.length-1)%tabs.length;else if(event.key==='Home')index=0;else if(event.key==='End')index=tabs.length-1;else return;event.preventDefault();tabs[index].click();};}
}
