function action(a){if(a==='shoot-back'){modal=null;recordHistory();render();return;}if(a.startsWith('edit-member-')){modal={type:'member-edit',id:a.slice(12)};render();return;}if(a==='new-library-reference'){navigate('library');return;}if(a==='load-references'){void openReferencePicker(state.project.id,reloadAfterMutation);return;}if(a==='members-add'){const projectId=state.project.id;openProjectMemberPicker({projectId,onAdded:reloadAfterMutation,beforeSubmit:()=>waitForProjectTeams(projectId),onRegister:()=>action('add-member')});return;}if(a==='refresh-shared'){refreshSharedProjectList();return;}if(a==='retry-save'){if(failed&&!saveConflict&&lastSaveOptions){failed=false;save(lastSaveOptions);}return;}if(a==='schedule-list'||a==='schedule-calendar'){scheduleView=a==='schedule-list'?'list':'calendar';recordHistory();render();return;}if(a==='toggle-sidebar'){setSidebarOpen(!sidebarOpen);}else if(a==='production'){navigate(lastProjectView);}else if(a==='add-project'){modal={type:'new-project'};sidebarOpen=false;render();}else if(a==='close'){modal=modal?.returnShootPage||null;render()}else if(a==='go-shoot'){navigate('shoot')}else if(a==='go-schedule'){navigate('schedule')}else if(a==='go-refs'||a==='modal-refs'){navigate('references')}else if(a==='modal-camera'){navigate('camera')}else if(a==='add-task'){document.querySelector('#new-task-name')?.focus();}else if(a==='add-content'){modal={type:'form',kind:'촬영 추가'};render()}else if(a==='add-line'||a==='add-text'){modal={type:'form',kind:'사람·사물 추가',placementKind:a==='add-line'?'arrow':'text'};render()}else if(a==='add-light'){modal={type:'form',kind:'사람·사물 추가',placementKind:'lighting'};render()}else if(a==='add-placement'){modal={type:'form',kind:'사람·사물 추가',placementKind:'person'};render()}else if(a==='add-camera'){modal={type:'form',kind:'카메라 추가'};render()}else if(a==='add-member'){modal={type:'form',kind:'멤버 추가'};render()}else if(a==='add-gear'){modal={type:'form',kind:'장비 추가'};render()}else if(a==='add-ref'){modal={type:'form',kind:'레퍼런스 그룹 추가'};render()}else if(a.startsWith('camera-')){modal={type:'camera',id:a.slice(7)};render()}else if(a==='toggle-script'){let c=state.contents.find(x=>x.id===modal.id);c.script=!c.script;save()}else if(a==='complete-current'){let c=state.contents.find(x=>!x.completed);if(c){c.completed=true;save()}}else if(a==='logout'){logout().catch(e=>alert(e.message));}else if(a==='project-settings'){modal={type:'project'};render();}else if(a==='script'){const c=state.contents.find(x=>!x.completed);if(c){modal={type:'content',id:c.id,tab:'materials'};recordHistory();render();}}}

