 const rect=stage.getBoundingClientRect(),inside=r=>r.left>=rect.left+2&&r.right<=rect.right-2&&r.top>=rect.top+2&&r.bottom<=rect.bottom-2;
 if(handles.some(handle=>inside(handle.getBoundingClientRect())))return;
