   const item=[...state.cameras,...state.layoutObjects].find(x=>x.id===button.dataset.layoutId),start=structuredClone(item),edge=e.target.closest('[data-resize]')?.dataset.resize,rotating=Boolean(e.target.closest('[data-rotate]'))&&Boolean(item.kind),geometry=layoutItemGeometry(item,stageElement.clientWidth,stageElement.clientHeight);
   const point=event=>({x:(event.clientX-stageRect.left)*scaleX-stageElement.clientLeft,y:(event.clientY-stageRect.top)*scaleY-stageElement.clientTop}),pointerStart=point(e);let moved=false,snapState=null;
